/**
 * The graphic design graph (Facets design §3.5): the design
 * system itself as nodes and edges, DERIVED from the project on
 * disk — token source (§3.4), guide record (§3.3), icon sets, and
 * the codebase map's component registry. Hand edits add notes
 * and grouping (the guide's component notes); derived facts are
 * never hand-maintained — re-derivation reconciles, the same
 * rule as Tech Stack derivation (§6).
 *
 * Canonical state at `ai-design/graph.json`, regenerated by
 * derivation; the report is computed from the graph plus a scan
 * of the project's text files, and is never stored.
 */
import fs from 'node:fs'
import path from 'node:path'
import { getFsRoot, listProjectFiles } from '../launcher.js'
import { buildMapForRoot } from '../codebaseMap/mapStore.js'
import { getDesignGuide, type DesignGuide, type TokenSourceKind } from './designGuide.js'

export const DESIGN_GRAPH_FILE = 'graph.json'

export type DesignNodeKind = 'token-group' | 'token' | 'type-step' | 'icon-set' | 'icon' | 'component' | 'layout-pattern'
export type DesignEdgeType = 'contains' | 'uses-token' | 'uses-type' | 'uses-icon' | 'aliases'

export interface DesignNode {
  id: string
  kind: DesignNodeKind
  name: string
  /** Token nodes: the token's value. Type steps: the size. */
  value?: string
  /** Token nodes: the group they belong to. */
  group?: string
  /** Component/icon nodes: the project-relative file. */
  file?: string
  note?: string
}

export interface DesignEdge { from: string, to: string, type: DesignEdgeType }

export interface DesignGraph {
  version: 1
  derivedAt: number
  source?: { kind: TokenSourceKind, file: string }
  nodes: DesignNode[]
  edges: DesignEdge[]
}

export interface DesignReport {
  unusedTokens: string[]
  hardcoded: { value: string, count: number, files: string[] }[]
  contrastFlags: { background: string, text: string, ratio: number }[]
  unseenTypeSteps: string[]
  componentsMissingFromGuide: string[]
  guideComponentsNotFound: string[]
}

/* ── Token source detection (§3.4) ─────────────────────────── */

export function detectTokenSource(root: string, guide: DesignGuide | null): { kind: TokenSourceKind, file: string } | null {
  if (guide?.tokens?.file) {
    const file = guide.tokens.file
    const kind = guide.tokens.source ?? (file.endsWith('.json') ? 'tokens-json' : /tailwind/i.test(file) ? 'tailwind' : 'css-variables')
    if (fs.existsSync(path.join(root, file))) return { kind, file }
  }
  const entries = listProjectFiles(root).map(e => e.path.replace(/^\//, ''))
  const tokensJson = entries.find(p => /(^|\/)design-tokens\.json$/.test(p)) ?? entries.find(p => /(^|\/)tokens\.json$/.test(p))
  if (tokensJson) return { kind: 'tokens-json', file: tokensJson }
  const css = entries.filter(p => p.endsWith('.css'))
  const preferred = css.find(p => /(theme|tokens|variables)\.css$/.test(p))
  for (const file of [preferred, ...css].filter((x): x is string => Boolean(x))) {
    try {
      const text = fs.readFileSync(path.join(root, file), 'utf-8')
      if (/--[\w-]+\s*:/.test(text)) return { kind: 'css-variables', file }
    } catch { /* keep looking */ }
  }
  const tailwind = entries.find(p => /(^|\/)tailwind\.config\.(js|ts|mjs|cjs)$/.test(p))
  if (tailwind) return { kind: 'tailwind', file: tailwind }
  return null
}

/* ── Token parsing ─────────────────────────────────────────── */

export interface RawToken { name: string, value: string, group: string }

const COLOUR_VALUE = /^(#|rgb|hsl|oklch|oklab|color\()/i

export function tokenGroup(name: string, value: string): string {
  const parts = name.toLowerCase().split(/[-_]/)
  const has = (...words: string[]) => parts.some(p => words.includes(p))
  if (has('radius', 'rounded', 'corner')) return 'radius'
  if (has('shadow', 'elevation', 'elev')) return 'elevation'
  if (has('duration', 'ease', 'easing', 'transition', 'motion', 'delay')) return 'motion'
  if (has('space', 'spacing', 'gap', 'pad', 'padding', 'margin', 'inset')) return 'spacing'
  if (has('font', 'text', 'type', 'leading', 'tracking') && !COLOUR_VALUE.test(value.trim())) return 'typography'
  if (has('color', 'colour', 'bg', 'background', 'surface', 'border', 'fill', 'stroke', 'ink', 'text', 'foreground', 'accent', 'primary', 'secondary') || COLOUR_VALUE.test(value.trim())) return 'colour'
  if (has('size', 'width', 'height') || /^-?[\d.]+(px|rem|em)$/.test(value.trim())) return 'spacing'
  return 'other'
}

export function parseCssVariables(text: string): RawToken[] {
  const out = new Map<string, string>()
  for (const m of text.matchAll(/--([\w-]+)\s*:\s*([^;]+);/g)) {
    out.set(m[1], m[2].trim())
  }
  return [...out.entries()].map(([name, value]) => ({ name, value, group: tokenGroup(name, value) }))
}

export function parseTokensJson(text: string): RawToken[] {
  let parsed: unknown
  try { parsed = JSON.parse(text) } catch { return [] }
  const out: RawToken[] = []
  const walk = (node: unknown, trail: string[]) => {
    if (!node || typeof node !== 'object') return
    const rec = node as Record<string, unknown>
    const value = rec.$value ?? rec.value
    if (typeof value === 'string' || typeof value === 'number') {
      const name = trail.join('-')
      out.push({ name, value: String(value), group: trail[0] ?? 'other' })
      return
    }
    for (const [k, v] of Object.entries(rec)) {
      if (k.startsWith('$')) continue
      walk(v, [...trail, k])
    }
  }
  walk(parsed, [])
  return out
}

/** Best-effort Tailwind derivation: top-level keys of the colors /
 * fontSize / spacing objects in the config text. A config whose
 * theme is built programmatically yields no tokens — derivation
 * then honestly reports the source with zero tokens. */
export function parseTailwindTokens(text: string): RawToken[] {
  const out: RawToken[] = []
  const blockKeys = (block: string): string[] => {
    const keys: string[] = []
    const start = text.indexOf(`${block}:`)
    if (start < 0) return keys
    const open = text.indexOf('{', start)
    if (open < 0) return keys
    let depth = 0
    let i = open
    for (; i < text.length; i++) {
      if (text[i] === '{') depth++
      else if (text[i] === '}') { depth--; if (depth === 0) break }
      else if (depth === 1) {
        const m = /^['"]([\w-]+)['"]\s*:/.exec(text.slice(i, i + 60)) ?? /^(\w+)\s*:/.exec(text.slice(i, i + 60))
        if (m) { keys.push(m[1]); i += m[0].length }
      }
    }
    return keys
  }
  for (const k of blockKeys('colors')) out.push({ name: `color-${k}`, value: '(tailwind palette)', group: 'colour' })
  for (const k of blockKeys('fontSize')) out.push({ name: `font-size-${k}`, value: '(tailwind scale)', group: 'typography' })
  for (const k of blockKeys('spacing')) out.push({ name: `spacing-${k}`, value: '(tailwind scale)', group: 'spacing' })
  return out
}

export function readTokens(root: string, source: { kind: TokenSourceKind, file: string }): RawToken[] {
  let text: string
  try { text = fs.readFileSync(path.join(root, source.file), 'utf-8') } catch { return [] }
  if (source.kind === 'tokens-json') return parseTokensJson(text)
  if (source.kind === 'tailwind') return parseTailwindTokens(text)
  return parseCssVariables(text)
}

/* ── Derivation ────────────────────────────────────────────── */

export function deriveDesignGraph(root: string = getFsRoot()): DesignGraph {
  const guide = getDesignGuide(root)
  const source = detectTokenSource(root, guide)
  const nodes: DesignNode[] = []
  const edges: DesignEdge[] = []
  const addNode = (n: DesignNode) => { if (!nodes.some(x => x.id === n.id)) nodes.push(n) }
  const addEdge = (e: DesignEdge) => { if (!edges.some(x => x.from === e.from && x.to === e.to && x.type === e.type)) edges.push(e) }

  if (source) {
    const tokens = readTokens(root, source)
    const groups = new Map<string, number>()
    for (const t of tokens) {
      groups.set(t.group, (groups.get(t.group) ?? 0) + 1)
      addNode({ id: `group:${t.group}`, kind: 'token-group', name: t.group })
      addNode({ id: `token:${t.name}`, kind: 'token', name: t.name, value: t.value, group: t.group })
      addEdge({ from: `group:${t.group}`, to: `token:${t.name}`, type: 'contains' })
      const alias = /var\(--([\w-]+)\)/.exec(t.value)
      if (alias && alias[1] !== t.name) addEdge({ from: `token:${t.name}`, to: `token:${alias[1]}`, type: 'aliases' })
    }
  }

  for (const step of guide?.typography?.scale ?? []) {
    addNode({ id: `type:${step.step}`, kind: 'type-step', name: step.step, value: step.size, note: step.role })
  }
  for (const bp of guide?.layout?.breakpoints ?? []) {
    addNode({ id: `layout:${bp.name}`, kind: 'layout-pattern', name: bp.name, value: `${bp.minWidth}px` })
  }

  for (const set of guide?.icons?.sets ?? []) {
    addNode({ id: `icon-set:${set.name}`, kind: 'icon-set', name: set.name, file: set.source })
    if (set.source && !set.source.includes('://')) {
      const dir = path.join(root, set.source)
      try {
        for (const f of fs.readdirSync(dir).filter(f => /\.(svg|png|ico)$/i.test(f)).slice(0, 120)) {
          const iconName = f.replace(/\.(svg|png|ico)$/i, '')
          addNode({ id: `icon:${set.name}/${iconName}`, kind: 'icon', name: iconName, file: `${set.source}/${f}` })
          addEdge({ from: `icon-set:${set.name}`, to: `icon:${set.name}/${iconName}`, type: 'contains' })
        }
      } catch { /* a package-named set has no directory to list */ }
    }
  }

  // Components: the codebase map's registry, with the guide's
  // notes overlaid; uses-token / uses-type edges from each
  // component file's text.
  try {
    const map = buildMapForRoot(root)
    const guideNotes = new Map((guide?.components ?? []).map(c => [c.name, c.note]))
    for (const comp of map.components) {
      addNode({ id: `component:${comp.name}`, kind: 'component', name: comp.name, file: comp.file, ...(guideNotes.get(comp.name) ? { note: guideNotes.get(comp.name) } : {}) })
      let text = ''
      try { text = fs.readFileSync(path.join(root, comp.file), 'utf-8') } catch { /* derived node stands without edges */ }
      for (const m of text.matchAll(/var\(--([\w-]+)\)/g)) {
        addEdge({ from: `component:${comp.name}`, to: `token:${m[1]}`, type: 'uses-token' })
      }
      for (const step of guide?.typography?.scale ?? []) {
        if (text.includes(step.size)) addEdge({ from: `component:${comp.name}`, to: `type:${step.step}`, type: 'uses-type' })
      }
    }
  } catch { /* no map: the graph still carries tokens, type, icons */ }

  const graph: DesignGraph = {
    version: 1,
    derivedAt: Date.now(),
    ...(source ? { source } : {}),
    nodes, edges,
  }
  return graph
}

export function designGraphPath(root: string): string {
  return path.join(root, 'ai-design', DESIGN_GRAPH_FILE)
}

export function getDesignGraph(root: string = getFsRoot()): DesignGraph | null {
  try {
    const parsed = JSON.parse(fs.readFileSync(designGraphPath(root), 'utf-8')) as DesignGraph
    return parsed && parsed.version === 1 && Array.isArray(parsed.nodes) ? parsed : null
  } catch {
    return null
  }
}

export function saveDesignGraph(graph: DesignGraph, root: string = getFsRoot()): DesignGraph {
  fs.mkdirSync(path.join(root, 'ai-design'), { recursive: true })
  fs.writeFileSync(designGraphPath(root), JSON.stringify(graph, null, 2) + '\n', 'utf-8')
  return graph
}

/* ── Report ────────────────────────────────────────────────── */

const TEXT_EXT = /\.(css|tsx?|jsx?|html?|vue|svelte)$/i

function scanProjectText(root: string, exclude: Set<string>): { file: string, text: string }[] {
  const out: { file: string, text: string }[] = []
  for (const e of listProjectFiles(root)) {
    const rel = e.path.replace(/^\//, '')
    if (!TEXT_EXT.test(rel) || exclude.has(rel) || rel.startsWith('ai-design/')) continue
    if (e.size > 200_000) continue
    try { out.push({ file: rel, text: fs.readFileSync(path.join(root, rel), 'utf-8') }) } catch { /* raced deletion */ }
    if (out.length >= 400) break
  }
  return out
}

function hexToRgb(hex: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim())
  if (!m) return null
  let h = m[1]
  if (h.length === 3) h = h.split('').map(c => c + c).join('')
  return [parseInt(h.slice(0, 2), 16) / 255, parseInt(h.slice(2, 4), 16) / 255, parseInt(h.slice(4, 6), 16) / 255]
}

export function contrastRatio(a: string, b: string): number | null {
  const lum = (hex: string): number | null => {
    const rgb = hexToRgb(hex)
    if (!rgb) return null
    const [r, g, bl] = rgb.map(c => (c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)))
    return 0.2126 * r + 0.7152 * g + 0.0722 * bl
  }
  const la = lum(a)
  const lb = lum(b)
  if (la === null || lb === null) return null
  const [hi, lo] = la >= lb ? [la, lb] : [lb, la]
  return (hi + 0.05) / (lo + 0.05)
}

export function designReport(root: string, graph: DesignGraph, guide: DesignGuide | null = getDesignGuide(root)): DesignReport {
  // The token source file is scanned too: a hard-coded value in
  // its other rules is exactly the drift this report exists to
  // catch. Token values themselves are filtered by value below.
  const scanned = scanProjectText(root, new Set())
  const tokens = graph.nodes.filter(n => n.kind === 'token')
  const tokenValues = new Set(tokens.map(t => (t.value ?? '').trim().toLowerCase()))

  const usedTokens = new Set<string>()
  for (const e of graph.edges) {
    if (e.type === 'uses-token') usedTokens.add(e.to.replace(/^token:/, ''))
    if (e.type === 'aliases') usedTokens.add(e.to.replace(/^token:/, ''))
  }
  for (const { text } of scanned) {
    for (const m of text.matchAll(/var\(--([\w-]+)\)/g)) usedTokens.add(m[1])
  }
  const unusedTokens = tokens.map(t => t.name).filter(n => !usedTokens.has(n))

  const hard = new Map<string, { count: number, files: Set<string> }>()
  for (const { file, text } of scanned) {
    for (const m of text.matchAll(/#[0-9a-f]{3,8}\b|rgba?\([^)]*\)/gi)) {
      const value = m[0].toLowerCase()
      if (tokenValues.has(value)) continue
      const rec = hard.get(value) ?? { count: 0, files: new Set<string>() }
      rec.count++
      rec.files.add(file)
      hard.set(value, rec)
    }
  }
  const hardcoded = [...hard.entries()]
    .map(([value, r]) => ({ value, count: r.count, files: [...r.files].slice(0, 5) }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 20)

  const colourTokens = tokens.filter(t => t.group === 'colour' && hexToRgb(t.value ?? ''))
  const backgrounds = colourTokens.filter(t => /(bg|background|surface)/i.test(t.name))
  const texts = colourTokens.filter(t => /(text|foreground|ink|on-)/i.test(t.name))
  const contrastFlags: DesignReport['contrastFlags'] = []
  for (const bg of backgrounds) {
    for (const tx of texts) {
      const ratio = contrastRatio(bg.value!, tx.value!)
      if (ratio !== null && ratio < 4.5) contrastFlags.push({ background: bg.name, text: tx.name, ratio: Math.round(ratio * 100) / 100 })
    }
  }

  const typeSteps = graph.nodes.filter(n => n.kind === 'type-step')
  const unseenTypeSteps = typeSteps
    .filter(n => !graph.edges.some(e => e.type === 'uses-type' && e.to === n.id))
    .filter(n => !scanned.some(({ text }) => n.value && text.includes(n.value)))
    .map(n => n.name)

  const graphComponents = new Set(graph.nodes.filter(n => n.kind === 'component').map(n => n.name))
  const guideComponents = new Set((guide?.components ?? []).map(c => c.name))
  const componentsMissingFromGuide = guideComponents.size
    ? [...graphComponents].filter(n => !guideComponents.has(n))
    : []
  const guideComponentsNotFound = [...guideComponents].filter(n => !graphComponents.has(n))

  return { unusedTokens, hardcoded, contrastFlags, unseenTypeSteps, componentsMissingFromGuide, guideComponentsNotFound }
}
